def solve():
    N = int(input())
    A = [int(x) for x in input().split()]
    d = dict()
    for a in A:
        if a % 2 != (N+1) % 2 :
            return 0
        if a not in d.keys():
            d[a] = 1
        else:
            d[a] += 1
            if d[a] >= 3:
                return 0
    if 0 in d.keys() and d[0] >= 2:
        return 0
    N //= 2
    ans = 1
    for i in range(N):
        ans *= 2
        ans %= MOD
    return ans

