from collections import Counter
N = int(input())
A = [int(x) for x in input().split()]


def solve(N, A):
    counter = Counter(A)
    if N % 2 == 1:
        for a, n in counter.items():
            if a == 0 and n == 1:
                continue
            if a % 2 != 0 or n != 2:
                return 0
        return (2**(N//2)) % 1000000007
    else:
        for a, n in counter.items():
            if a % 2 != 1 or n != 2:
                return 0
        return (2**(N//2)) % 1000000007

print(solve(N, A))

