def solution(diffs):
    counts = {}
    for d in diffs:
        counts[d] = counts.get(d, 0) + 1

    odds = 0
    for diff, count in counts.items():
        if count % 2 != 0:
            odds += 1
            if odds > 1 or diff != 0:
                return 0

    pairs = len(diffs) // 2
    return (2**pairs) % (10**9 + 7)

