    if n == 0:
        return 1
    elif n == 1:
        return 2
    if n % 2 == 0:
        tmp = exp(n // 2) % 1000000007
        return (tmp * tmp) % 1000000007
    else:
        tmp = exp(n // 2) % 1000000007
        return (2 * tmp * tmp) % 1000000007
