    MOD = 10**9 + 7
    d = defaultdict(lambda: 0)
    for a in A:
        d[a] += 1
        if d[a] >= 3:
            return 0

    if not (d[0] == 0 or d[0] == 1):
        return 0

    cnt = 0
    A = set(A)
    for a in A:
        if a == 0:
            continue

        if d[a] != 2:
            return 0
        else:
            cnt += 1

    return (2**cnt) % MOD


