    primes = primes_eratosthenes(n)

    d = {}

    for i in range(2,n+1):
        d = add_factor(d, i, primes)

    MOD = 10**9 + 7
    ans = 1
    for v in d.values():
        ans = ans * (v+1) % MOD

    return ans


