def __sieve(num):
    sieved_set = set()
    for i in range(2, num + 1):
        sieved_set.add(i)

    # エラトステネスの篩法で素数を計算する
    for i in range(2, int(math.sqrt(num)) + 1):
        for j in range(2, num + 1):
            if (j % i == 0) and (j != i) and (j in sieved_set):
                sieved_set.remove(j)

    return sieved_set


