    def __init__(self, x=0):
        self.x = (x%self.MOD + self.MOD) % self.MOD

    def __iadd__(self, other):
        self.x += other.x
        if self.x >= self.MOD:
            self.x -= self.MOD
        return self

    def __isub__(self, other):
        self.x += self.MOD - other.x
        if (self.x >= self.MOD):
