        return self

    def __imul__(self, other):
        self.x *= other.x
        self.x %= self.MOD;
        return self;

    def __add__(self, other):
        ans = Mint(self.x)
        ans += other
        return ans

    def __sub__(self, other):
        ans = Mint(self.x)
        ans -= other
        return ans

    def __mul__(self, other):
        ans = Mint(self.x)
        ans *= other
        return ans

    def __pow__(self, n):
        if n == 0:
            return Mint(1)
        a = self.__pow__(n >> 1)
        a *= a
        if n&1:
            a *= self
        return a

    def inv(self):
        return self**(self.MOD-2)

    def __ifloordiv__(self, other):
        self *= other.inv()
        return self

    def __floordiv__(self, other):
        ans = Mint(self.x)
        ans //= other
        return ans


