# An integer x is factored into x = p**n × q
# When m × ... (p, q, ... is a prime number), the number of divisors of x is
# (n + 1) × (m + 1) × ... Therefore, for all prime factors of N !, N! Is divisible by the prime factors.
# You just have to ask. And how many times N! Is divided by which prime factor depends on which prime number from 1 to N is.
# You can find it by finding how many times it can be divided by a factor and adding them together. The problem this time is that N is small, so I implemented this straightforwardly
# You can solve it.

allPrimes = []

def sieve(n):

	prime = [True] * (n + 1)

	p = 2
	while(p * p <= n):

		if (prime[p] == True):

			i = p * 2;
			while(i <= n):
				prime[i] = False
				i += p
		p += 1

	for p in range(2, n + 1):
		if (prime[p]):
			allPrimes.append(p);

def factorialDivisors(n):

	sieve(n)

	result = 1

	for i in range(len(allPrimes)):

		p = allPrimes[i]

		exp = 0
		while (p <= n):
			exp += n//p
			p *= allPrimes[i]

		result = result * (exp + 1)

	return result

