def eratosthenes(N):
    is_prime = [True] * (N + 1)
    is_prime[0] = is_prime[1] =False
    for i in range(2, int(sqrt(N)) + 1):
        if is_prime[i]:
            for j in range(2 * i, N + 1, i):
                is_prime[j] = False
    return is_prime


def prime_factorization(N, is_prime):
    divisors = []
    n = N
    for i, p in enumerate(is_prime[2:], start=2):
        if not p:
            continue
        while n % i == 0:
            divisors.append(i)
            n //= i
    return divisors


def count_divisor(divisors):
    grouped_divisors = collections.Counter(divisors)
    divisor_num = 1
    for _, v in grouped_divisors.items():
        divisor_num *= (v + 1)
    return divisor_num


