def factorize(n: int) -> List[int]:
    factors = []

    while n % 2 == 0:
        factors.append(2)
        n = int(n / 2)

    fmax = int(math.sqrt(n)) + 1
    for i in range(3, fmax, 2):
        while n % i == 0:
            factors.append(i)
            n = int(n / i)

    if n > 2:
        factors.append(n)

    return factors


