def Eratosthenes(x: int) -> set:
    """x以下の素数のsetを返す"""
    import math
    sup = int(x)
    primes = {i for i in range(2,sup+1)}
    for i in range(2,int(math.sqrt(sup+1))+1):
        if i in primes:
            mul = 2
            while i*mul <= sup:
                primes.discard(i*mul)
                mul += 1
    return primes

