def check(image_a, image_b, offset):
    m = len(image_b)

    for i in range(m):
        for j in range(m):
            if image_b[i][j] != image_a[i + offset[0]][j + offset[1]]:
                return False

    return True


def solve():
    n, m = read_ints()

    image_a = []
    for _ in range(n):
        image_a.append(input())

    image_b = []
    for _ in range(m):
        image_b.append(input())

    # loop: O(N^2) <= 2500
    # loop * check: O(N^2 * M^2) <= 6250000
    for offset_i in range(n - m + 1):
        for offset_j in range(n - m + 1):
            if check(image_a, image_b, (offset_i, offset_j)):
                print('Yes')
                return

    print('No')


