import itertools


def judge(n, m, fig_a, fig_b):
    for dr, dc in itertools.product(range(n - m + 1), repeat=2):
        g = itertools.product(range(m), repeat=2)
        if all(fig_a[r0 + dr][c0 + dc] == fig_b[r0][c0] for r0, c0 in g):
            return True
    return False


def main():
    n, m = (int(x) for x in input().split())
    fig_a = [[c == "#" for c in input()] for _ in range(n)]
    fig_b = [[c == "#" for c in input()] for _ in range(m)]
    print("Yes" if judge(n, m, fig_a, fig_b) else "No")


if __name__ == '__main__':
    main()

