def num_paths(trail, num_all_nodes, edges):
    if len(trail) == num_all_nodes:
        return 1

    count = 0
    for dest in edges[trail[len(trail)-1]]:
        if dest in trail:
            continue
        count += num_paths(trail + [dest], num_all_nodes, edges)
    return count


