def dfs(graph, now, done):
    result = 0
    doneCache = copy.deepcopy(done)
    doneCache.append(now)
    if len(doneCache) == N:
        return 1
    for a,b in graph:
        if a == now:
            if b not in doneCache:
                result += dfs(graph, b, doneCache)
        if b == now:
            if a not in doneCache:
                result += dfs(graph, a, doneCache)

    return result

