def build_graph(edges):
    graph = {}

    for edge in edges:
        a,b = edge
        if a not in graph:
            graph[a] = []
        if b not in graph:
            graph[b] = []

        graph[a].append(b)
        graph[b].append(a)

    return graph

def dfs(graph,path,n,res):
    current = path[-1]
    if len(path) == n:
        path = tuple(path)
        if path not in res:
            res.add(path)
            return
    else:
        for neighbor in graph[current]:
            if neighbor not in path:
                path.append(neighbor)
                dfs(graph,path,n,res)
                path.pop()
    return


def answer(edges,n):
    graph = build_graph(edges)
    res = set()

    for i in range(n):
       dfs(graph,[1],n,res)

