class Graph_dfs():
    def __init__(self, V):
        self.G = [[] for i in range(V)]  # 隣接リストG[u][i] := 頂点uのi個目の隣接辺
        self.flag = [0 for i in range(V)]
        self._E = 0  # 辺の数
        self._V = V  # 頂点の数
        self.count=0

    def E(self):
        return self._E

    def V(self):
        return self._V

    def add(self, _from, _to):
        self.G[_from].append(_to)
        self.G[_to].append(_from)
        self._E += 1

    def dfs(self,u,length):
        length=length+1
        self.flag[u]=1
        if length==self._V:
            self.count+=1
        for v in self.G[u]:
            if self.flag[v]==0:
                self.dfs(v,length)
        length-=1
        self.flag[u]=0
        return self.count

