import sys

read = sys.stdin.buffer.read
readline = sys.stdin.buffer.readline

def from_readline():
    return [int(x) for x in readline().split()]

def read_matrix(N, M):
    matrix = [None for i in range(N)]
    for i in range(N):
        matrix[i] = from_readline()
    return matrix

def solve(a, b, x):
    return (b // x) - ((a - 1) // x)

def main():
    a, b, x = from_readline()
    print(solve(a, b, x))

