def read_input():
    sx, sy, tx, ty = map(int, input().split())

    return (sx, sy), (tx, ty)


def get_right(point):
    return (point[0] + 1, point[1])


def get_left(point):
    return (point[0] - 1, point[1])


def get_up(point):
    return (point[0], point[1] + 1)


def get_down(point):
    return (point[0], point[1] - 1)


def go_right_up(sp, ep):
    move = []
    curr = sp

    while curr[0] < ep[0]:
        move.append('R')
        curr = get_right(curr)

    while curr[1] < ep[1]:
        move.append('U')
        curr = get_up(curr)

    return move


def go_left_down(sp, ep):
    move = []
    curr = sp

    while ep[0] < curr[0]:
        move.append('L')
        curr = get_left(curr)

    while ep[1] < curr[1]:
        move.append('D')
        curr = get_down(curr)

    return move


def submit():
    start, end = read_input()

    start1 = get_right(start)
    end1 = get_down(end)

    start2 = get_left(end)
    end2 = get_up(start)

    start3 = get_down(start)
    end3 = get_right(end)

    start4 = get_up(end)
    end4 = get_left(start)


    move = ['R']
    move += go_right_up(start1, end1)
    move += ['U']

    move += ['L']
    move += go_left_down(start2, end2)
    move += ['D']

    move += ['D']
    move += go_right_up(start3, end3)
    move += ['L']

    move += ['U']
    move += go_left_down(start4, end4)
    move += ['R']

    print(''.join(move))


if __name__ == '__main__':
    submit()

