class Heap:
    def __init__(self, data=None):
        if data is None:
            self.data = []
        else:
            self.data = data

    def push(self, x):
        heappush(self.data, x)

    def pop(self):
        return heappop(self.data)

    @property
    def min(self):
        return self.data[0]

    def __iter__(self):
        return iter(self.data)


