def solve(N, LIM):
    ax = list(map(int, input().split()))
    ans = 0
    left = ax[0]

    for i in range(N-2):
        # left right
        right = ax[i+1]
        total = left + right
        should_eat = total - LIM
        if should_eat > 0:
            ans += should_eat
            if should_eat < right:
                left = right - should_eat
            else:
                left = 0
        else:
            left = right

    ans += (left + ax[-1]) - LIM if (left+ax[-1]) > LIM else 0
    return ans


