class Mod:
    mod = MOD

    def __init__(self, x: int) -> None:
        self.x = x % self.mod

    def __add__(self, other: Union["Mod", int]) -> "Mod":
        if isinstance(other, int):
            return Mod(self.x + other)
        return Mod(self.x + other.x)

    def __sub__(self, other: Union["Mod", int]) -> "Mod":
        if isinstance(other, int):
            return Mod(self.x - other)
        return Mod(self.x - other.x)

    def __mul__(self, other: Union["Mod", int]) -> "Mod":
        if isinstance(other, int):
            return Mod(self.x * other)
        return Mod(self.x * other.x)

    def __truediv__(self, other: Union["Mod", int]) -> "Mod":
        if isinstance(other, int):
            return Mod(self.x // other)
        return Mod(self.x * other.inv().x)

    def __eq__(self, other: "Mod") -> bool:
        return self.x == other.x

    def __le__(self, other: "Mod") -> bool:
        return self.x <= other.x

    def __lt__(self, other: "Mod") -> bool:
        return self.x < other.x

    def __ge__(self, other: "Mod") -> bool:
        return self.x >= other.x

    def __gt__(self, other: "Mod") -> bool:
        return self.x > other.x

    def __ne__(self, other: "Mod") -> bool:
        return self.x != other.x

    def inv(self) -> "Mod":
        a = self.x
        b = self.mod
        u, v = 1, 0
        while b > 0:
            t = a // b
            a, b = b, a - t * b
            u, v = v, u - t * v
        return Mod(u)

    def __pow__(self, ex: int) -> "Mod":
        a = self.x
        res = 1
        while ex > 0:
            if ex & 1:
                res = (res * a) % self.mod
            a = (a * a) % self.mod
            ex >>= 1
        return Mod(res)

    def __str__(self) -> str:
        return str(self.x)

    def __repr__(self) -> str:
        return str(self.x)

