# s is start vertex
def bfs(N, graph, s):
    dist = [-1]*N
    dist[s] = 0
    d = deque()
    d.append(s)

    while d:
        v = d.popleft()
        for i in graph[v]:
            if dist[i] != -1:
                continue
            dist[i] = dist[v]+1
            d.append(i)
    return dist


