    N, M = read_nums() # N: 目的の島 2*10e5 M: 定期便の種類 2*10e5
    h = {}
    for _ in range(M):
        n, m = read_nums()
        if n not in h:
            h[n] = set([m])
        else:
            h[n].add(m)

    # そもそも島1から出られない
    if 1 not in h:
        print('IMPOSSIBLE')
        return

    # 島1 -> i -> N
    for i in h[1]: # O(N)
        if i not in h:
        # 島iから先に出る船はない
            continue
        # 島
        if N in h[i]: # O(1)
            print('POSSIBLE')
            return
    print('IMPOSSIBLE')


