N, M = map(int, input().split())
G = []
for _ in range(N):
    G.append([])
for _ in range(M):
    ai, bi = map(int, input().split())
    ai -= 1
    bi -= 1
    G[ai].append(bi)
    G[bi].append(ai)

dist = [-1]*N
Q = deque()
Q.append(0)

dist[0] = 0

while Q:
    i = Q.popleft()
    if dist[i] == 2:
        continue

    for j in G[i]:
        if dist[j] == -1:
            dist[j] = dist[i] + 1
            Q.append(j)

if 1 <= dist[N-1] <= 2:
