import sys
sys.setrecursionlimit(300000)


def solve(N: int, M: int):
    if N * 2 >= M:
        ret = M // 2
    else:
        left = M - N * 2
        ret = N + left // 4
    print(ret)
    return


def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    M = int(next(tokens))  # type: int
    solve(N, M)

if __name__ == '__main__':
    main()

