def divisors(n):
    def factorize(n):
        f = []
        p = 2
        while p**2 <= n:
            if n % p == 0:
                n //= p
                e = 1
                while n % p == 0:
                    n //= p
                    e += 1
                f.append((p, e))
            p += 1
        if n > 1:
            f.append((n, 1))
        return f

    def dfs(f, pos=0, d=1):
        yield d
        for i in range(pos, len(f)):
            p, e = f[i]
            u = d * p
            for j in range(1, e+1):
                yield from dfs(f, i+1, u)
                u *= p

    f = factorize(n)
    yield from dfs(f)


