def search_nearest_checkpoint(st, checks):
    def manhattan_dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    mindist = float('inf')
    minid = None
    for i, check in enumerate(checks):
        mdist = manhattan_dist(st, check)
        if mdist < mindist:
            mindist = mdist
            minid = i + 1

    return minid

