    l_ls = [0] * int(np.floor(0.5*n))
    r_ls = [0] * max(0,(n-1)//2)
    first = q.popleft()
    count = 2
    while True:
        a = q.popleft()
        if count % 2 == 0:
            l_ls[count//2-1] = a
        else:
            r_ls[count//2-1] = a
        count += 1
        if count > n:
            break
    ans = []
    if n % 2 ==0:
        for i in range(len(l_ls)):
            l = l_ls.pop()
            ans.append(l)
        ans.append(first)
        for i in range(len(r_ls)):
            ans.append(r_ls[i])
    else:
        for i in range(len(r_ls)):
            l = r_ls.pop()
            ans.append(l)
        ans.append(first)
        for i in range(len(l_ls)):
            ans.append(l_ls[i])

    ans = [str(b) for b in ans]
    print(' '.join(ans))

