# +, -, + or -, +, -


def solve(first, a):
    res = 0
    wa = a[0]
    if a[0] * first <= 0:
        res = abs(first - a[0])
        wa = first
    for i in range(1, n):
        pwa = wa + a[i]
        if wa * pwa >= 0:
            if wa > 0:
                res += abs(-1 - pwa)
                wa = -1
            else:
                res += abs(1 - pwa)
                wa = 1
        else:
            wa = pwa
    return res


print(min(solve(1, a), solve(-1, a)))

def c_sequence():
    N = int(input())
    A = [int(i) for i in input().split()]

    def solver(sign):
        ret, total = 0, 0
        for a in A:
            total += a
            if sign * total <= 0:
                ret += abs(sign - total)  # 総和がsignになるまでaを変化させる
                total = sign
            sign *= -1
        return ret
    # 1: 奇数番目を正、偶数番目を負にする場合。 -1: その逆
    return min(solver(1), solver(-1))

print(c_sequence())

