import sys


def solve(n: int, a: "List[int]"):
    def _solve(op):
        from itertools import cycle
        ab = 0
        for aa in map(lambda a_o: a_o[0]*a_o[1], zip(a, cycle(op))):
            ab -= aa
            if ab >= 0:
                yield ab + 1
                ab = -1
            ab = abs(ab)
    return min(sum(_solve([1, -1])), sum(_solve([-1, 1])))

