def solve():
    N = II()
    A = LI()
    Acum= [0 for i in range(N)]
    Acum[0] = A[0]
    #負正負正…または正負正負で操作回数の少ない方
    for i in range(1,N):
        Acum[i] = Acum[i-1] + A[i]
    from copy import deepcopy
    Aplus = deepcopy(Acum)
    Num = 0
    PlusOpe = 0
    for i in range(N):
        ChangeA = Aplus[i] + Num
        if(i%2 == 0):
            if(ChangeA<=0):
                Num += abs(1-ChangeA)
                PlusOpe += abs(1-ChangeA)
        else:
            if(ChangeA>=0):
                Num -= abs(ChangeA)+1
                PlusOpe += abs(ChangeA)+1
    Aminus = deepcopy(Acum)
    Num = 0
    MinusOpe = 0
    for i in range(N):
        ChangeA = Aminus[i] + Num
        if(i%2 == 1):
            if(ChangeA<=0):
                Num += abs(1-ChangeA)
                MinusOpe += abs(1-ChangeA)
        else:
            if(ChangeA>=0):
                Num -= abs(ChangeA)+1
                MinusOpe += abs(ChangeA)+1
    print(min(MinusOpe,PlusOpe))
    return
