def solve(N: int, S: str):
    X = ""
    counter = 0                 # counterは(の数
    for i, c in enumerate(S):
        if c == ')' and counter == 0:
            X = '(' + X + ')'
        elif c == ')' and counter > 0:
            X = X + ')'
            counter -= 1
        elif c == '(':
            X = X + '('
            counter += 1
    X += ')'*counter
    print(X)
    return


