import sys


def solve(N: int, S: str):
    left = 0
    left_max = 0
    for i in range(N):
        if S[i] == ')':
            left += 1
        elif S[i] == '(':
            left -= 1
        if left > left_max:
            left_max = left

    right = 0
    right_max = 0
    for i in range(N-1, -1, -1):
        if S[i] == '(':
            right += 1
        elif S[i] == ')':
            right -= 1
        if right > right_max:
            right_max = right
    print('(' * left_max + S + ')' * right_max)
    return


