import math
MOD = 1000000007  # type: int


def solve(N: int, M: int):
    if abs(N-M) >= 2:
        print(0)
        return 

    ## Nの並び替えパターン
    N_number = math.factorial(N)%MOD
    M_number = math.factorial(M)%MOD

    if N == M:
        print((N_number*M_number*2)%MOD)
    else:
        print((N_number*M_number)%MOD)
    return


