def fractorial(n, MOD):
    frac = [1] * (n+1)
    for i in range(2, n+1):
        frac[i] = frac[i-1] * i
        frac[i] %= MOD
    return frac


def solve(N, M, MOD=10**9+7):
    if N > M:
        N, M = M, N
    ans = 0
    if M - N <= 1:
        frac = fractorial(M, MOD)
        if N == M:
            ans = frac[N] * frac[M] * 2
            ans %= MOD
            return ans
        else:
            ans = frac[N] * frac[M]
            ans %= MOD
    return ans


