def factorial(num: int) -> int:
    mod = pow(10, 9) + 7
    result = 1
    for i in range(1, num + 1):
        result *= i
        result %= mod

    return result


def solve(n: int, m: int) -> int:
    if 2 <= abs(n - m):
        return 0

    mod = pow(10, 9) + 7
    if n == m:
        return 2 * factorial(n) * factorial(m) % mod

    return factorial(n) * factorial(m) % mod


def main():
    n, m = map(int, input().split())
    print(solve(n, m))


