def read():
    N = int(input().strip())
    S = []
    for i in range(N):
        s = input().strip()
        S.append(s)
    return N, S


def a2i(a):
    return ord(a) - ord("a")


def i2a(i):
    return chr(ord("a") + i)


def solve(N, S):
    A = [1000000 for i in range(26)]
    for s in S:
        B = [0 for i in range(26)]
        for c in s:
            B[a2i(c)] += 1
        for i in range(26):
            A[i] = min(A[i], B[i])
    ans = []
    for i in range(26):
        ans.append(i2a(i) * A[i])
    return "".join(ans)


if __name__ == '__main__':
    inputs = read()
    outputs = solve(*inputs)
    if outputs is not None:
        print("%s" % str(outputs))

