    common = defaultdict(str)  # 文字列の中で共通する文字の一覧と個数
    for c in 'abcdefghijklmnopqrstuvwxyz':
        low = float('inf')
        for i in range(N):
            low = min(low, d[i][c])
        if low == 0:
            continue
        else:
            common[c] = low
    common = sorted(common.items())

    ans = ''
    for c, v in common:
        ans += c * v
    return ans

