def read_pair_int()->(int,int):
    arr = input().split()
    arr1 = int(arr[0])
    arr2 = int(arr[1])
    return arr1,arr2

def read_trio_int()->(int,int,int):
    arr = input().split()
    arr1 = int(arr[0])
    arr2 = int(arr[1])
    arr3 = int(arr[2])
    return arr1,arr2,arr3

def read_list_int():
    arr = input().split()
    return np.array([int(i) for i in arr])

def read_int()->int:
    n = int(input())
    return n

def read_lines_int(n):
    d = [0] * n
    for i in range(n):
        d[i] = read_int()
    return np.array(d)

def read_lines(n):
    d = [0] * n
    for i in range(n):
        d[i] = input()
    return np.array(d)

def read_trio_lines_int(n)->int:
    d = [0] * (n)
    for i in range(n):
        d[i] = read_trio_int()
    return d

def read_pair_lines_int(n)->int:
    d = [0] * (n)
    for i in range(n):
        d[i] = read_pair_int()
    return d


