def bellman_ford(s, g):
    d = [float('inf')]*n # 各頂点への最小コスト
    d[s] = 0 # 自身への距離は0
    u_n = [0] * n # 頂点までの距離が更新されたかを管理するリスト
    for i in range(n):
        update = False # 更新が行われたか
        for x, y, z in g:
            if d[y] > d[x] + z:
                d[y] = d[x] + z
                update = True
                # 負の閉路が使用できるかの判定のための処理                
                if i == n - 1:
                    u_n[y] = 1
        if not update:
            break
        # 負閉路が存在
        if i == n - 1:
            # return -1
            return d, u_n # 更新の記録も併せて返す
    # return d
    return d, []

