def BFS(n, E, i0=0):
    Q = deque([i0])
    D = [-1] * n
    D[i0] = 0
    while Q:
        x = Q.popleft()
        for c, w in E[x]:
            if D[c] == -1:
                D[c] = D[x] + 1
                Q.append(c)
    return D


def bellman_ford(n, E, s=0):
    D = [1 << 100] * n
    D[s] = 0
    f = 1
    while f:
        f = 0
        for i in range(n):
            if not B[i]:
                continue
            for j, c in E[i]:
                if not B[j]:
                    continue
                if D[i] < 1 << 100 and D[j] > D[i] + c:
                    D[j] = D[i] + c
                    f = 1
    return D


def bellman_ford_check(n, E, s=0):
    D = [0] * n
    for k in range(n):
        for i in range(n):
