def BellmanFord(N, M, edges):
    d = [inf] * N
    d[0] = 0

    for i in range(N-1):
        for (u, v, c) in edges:
            if d[u] + c < d[v]:
                d[v] = d[u] + c

    for (u, v, c) in edges:
        if d[u] + c < d[v]:
            d[v] = -inf

    for i in range(N-1):
        for (u, v, c) in edges:
            if d[u] + c < d[v]:
                d[v] = -inf
            if v == N-1 and d[v] == -inf:
                return None
    return d[N-1]

