def Bellman_ford(G, s): #sから全点への最小経路を求める. negative cycleが絡む頂点は 最小経路 -float('inf')とする
    D = {s: float('inf') for s in G}
    D[s] = 0
    P = {s: None for s in G}
    for rnd in G: #n = len(G) ラウンド
        changed = False
        for u in G:
            for v in G[u]:
                d = D[u] + G[u][v]
                if d < D[v]:
                    D[v] = d
                    P[v] = u
                    changed = True
        if not changed: #変化がなかった場合終了. negative cycleが内場合、最大n-1回緩和サイクルが回り、n回目でbreakする。
            break
    else: #nラウンドで終了しなかった場合、負のサイクルがある. negative cycleが関係する頂点を検出する。
        d_end = D.copy()
        for u in G:
            for v in G[u]:
                d = D[u] + G[u][v]
                if d < D[v]:
                    D[v] = d
                    P[v] = u                 
        for u in G:
            if D[u] < d_end[u]: #負サイクルにより無限に小さい重みで到達できる頂点
                D[u] = -float('inf')          
    return D


