def read_strs(split_character=' '):
    data = input()
    return data.split(split_character)


def read_ints(split_character=' '):
    data_i = []
    for i in read_strs(split_character):
        data_i.append(int(i))
    return data_i

def read_floats(split_character=' '):
    data_f = []
    for i in read_strs(split_character):
        data_f.append(float(i))
    return data_f

