import string


def solve(N, Ss):
    Ss = sorted(Ss)
    if all([s % 10 == 0 for s in Ss]):
        return 0
    allsum = sum(Ss)
    if allsum % 10 != 0:
        return allsum
    for c in Ss:
        if (allsum - c) % 10 != 0:
            return allsum - c
    return 0

