def int_inputs(num_of_input):
    ins = [int(input()) for i in range(num_of_input)]
    return ins


def solve(inputs):
    S = inputs
    S.sort()
    total = reduce(lambda acc, x: acc+x, S, 0)
    if total % 10 == 0:
        for s in S:
            if s % 10 != 0:
                total -= s
