INF = float("inf")


def solve(N: int, s: "List[int]"):
    tot = sum(s)
    if tot % 10 != 0:
        print(tot)
        return
    m = INF
    for x in s:
        if x % 10 == 0:
            continue
        if x < m:
            m = x
    if m != INF:
        print(tot-m)
    else:
        print(0)

    return


