# 組み合わせ計算
def cmb(n, r):
    if n == r: return 1
    r = min(n - r, r)
    if r == 0: return 1
    over = reduce(mul, range(n, n - r, -1))
    under = reduce(mul, range(1, r + 1))
    return over // under


# 二分探索
def search(t, i):
    """
    t: list 探索元の数列
    i: int 探索する値
    """
    ix = bisect_right(t, i)
    if t[ix - 1] != i:
        return False
    return True


# 素因数分解。リスト形式で返す。Counterで個数を数えられる。
def prime_factorize(n):
    a = []
    while n % 2 == 0:
        a.append(2)
        n //= 2
    f = 3
    while f * f <= n:
        if n % f == 0:
            a.append(f)
            n //= f
        else:
            f += 2
    if n != 1:
        a.append(n)
    return a


# 素数判定
def isPrime(n):
    if n == 1: return False
    for k in range(2, int(sqrt(n)) + 1):
        if n % k == 0:
            return False
    return True


# MOD用組み合わせ
def mod_cmb(n: int, k: int, p: int) -> int:
    if n < 0 or k < 0 or n < k: return 0
    if n == 0 or k == 0: return 1
    if (k > n - k):
        return mod_cmb(n, n - k, p)
    c = d = 1
    for i in range(k):
        c *= (n - i)
        d *= (k - i)
        c %= p
        d %= p
    return c * pow(d, p - 2, p) % p


# 最小公倍数
def lcm(x, y):
    return (x * y) // gcd(x, y)


# 複数（リスト）の最大公約数
def gcds(*numbers):
    return reduce(gcd, numbers)


# 複数（リスト）の最小公倍数
def lcms(*numbers):
    return reduce(lcm, numbers, 1)


# 出現回数順に要素を取得
def most_common(x):
    return Counter(x).most_common()


# 約数列挙
def make_divisors(n):
    lower_divisors, upper_divisors = [], []
    i = 1
    while i * i <= n:
        if n % i == 0:
            lower_divisors.append(i)
            if i != n // i:
                upper_divisors.append(n // i)
        i += 1
    return lower_divisors + upper_divisors[::-1]


# 桁和
def digsum(n):
    s = str(n)
    array = list(map(int, s))
    return sum(array)


