class UnionFind:
    def __init__(self, size):
        self.parent = [-1] * size
        self.size = [1] * size

    def get_root(self, id):
        if self.parent[id] != -1:
            return self.get_root(self.parent[id])
        else:
            return id

    def is_same(self, id1, id2):
        root1 = self.get_root(id1)
        root2 = self.get_root(id2)
        return root1 == root2 and self.get_root(id1) != -1

    def unite(self, id1, id2):
        root1 = self.get_root(id1)
        root2 = self.get_root(id2)

        if root1 == root2 and root1 != -1: return None

        # 大きい方に小さい方をぶら下げる
        # サイズはrootの要素だけ管理しておけばいい
        if self.size[root1] > self.size[root2]:
            self.parent[root2] = root1
            self.size[root1] += self.size[root2]
        else:
            self.parent[root1] = root2
            self.size[root2] += self.size[root1]

    def get_group_size(self, id):
        return self.size[self.get_root(id)]


