        self.par = [i for i in range(n)] # 親
        self.rank = [0 for _ in range(n)] # 根の深さ

    # xの属する木の根を求める
    def find(self, x):
        if self.par[x] == x:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    # xとyの属する集合のマージ
    def unite(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x == y:
            return
        if self.rank[x] < self.rank[y]:
            self.par[x] = y
        else:
            self.par[y] = x
            if self.rank[x] == self.rank[y]:
                self.rank[x] += 1

    # xとyが同じ集合に属するかを判定
    def same(self, x, y):
        return self.find(x) == self.find(y)


def kruskal(n, edges):
    uf = UnionFind(n)
    cost = 0
    for e in edges:
        w, s, t = e
        if not uf.same(s, t):
            cost += w
            uf.unite(s, t)
    return cost


