class UnionFindTree:
    __slots__ = ('parent')

    def __init__(self, n: int) -> None:
        self.parent = [-1] * n

    def find(self, x: int) -> int:
        p = self.parent
        par, seq = p[x], []
        while par >= 0:
            seq.append(x)
            x, par = par, p[par]
        for c in seq: p[c] = x
        return x

    def union(self, x: int, y: int) -> bool:
        x, y, p = self.find(x), self.find(y), self.parent
        if x == y: return False
        if p[x] > p[y]: x, y = y, x
        p[x], p[y] = p[x] + p[y], x
        return True

    def same(self, x: int, y: int) -> bool:
        return self.find(x) == self.find(y)

    def size(self, x: int) -> int:
        return -self.parent[self.find(x)]

    def same_all(self, indices: Iterable[int]) -> bool:
        f, v = self.find, self.find(indices[0])
        return all(f(i) == v for i in indices)

    def roots(self) -> List[int]:
        return [i for i, p in enumerate(self.parent) if p < 0]

    def groups(self) -> Dict[int, List[int]]:
        res = dict()
        for i in range(len(self.parent)):
            r = self.find(i)
            if r not in res: res[r] = []
            res[r].append(i)
        return res

