class DSU:
    def __init__(self, arr):
        self.rank=[0]*len(arr)
        self.parent=arr[:]

    def find(self,node):
        if self.parent[node]!=node:
            self.parent[node]=self.find(self.parent[node])
        return self.parent[node]
    def union(self, a, b):
        a = self.find(a)
        b = self.find(b)
        if a!=b:
            if self.rank[a]>self.rank[b]:
                self.parent[b]=a
            elif self.rank[b]>self.rank[a]:
                self.parent[a]=b
            else:
                self.parent[b]=a
                self.rank[a]+=1
            return True
        return False

