import itertools

def calc(str, tup):
  l = []
  idx = 0
  for i in tup:
    l.append(int(str[idx:i]))
    idx = i
  l.append(int(str[idx:]))
  return sum(l)

def solve(s):
  l = [i for i in range(1, len(s))]
  ans = 0
  for c in range(len(l)+1):
    for v in itertools.combinations(l,c):
      ans += calc(s, v)
  return ans

