import itertools


def add_operators(numbers, operators):
    return ''.join([operators[i] + numbers[i] for i in range(len(numbers))])


def main(s):
    numbers = list(s)
    operators = [['']]
    operators.extend([['', '+']] * (len(numbers) - 1))
    products = itertools.product(*operators)
    sum_numbers = 0
    for p in products:
        sum_numbers += sum(map(int, add_operators(numbers, p).split('+')))
    return sum_numbers


