def bit_all_search(length):
    for i in range(2**length):
        bin_str = bin(i)[2:].zfill(length)
        indexes = []
        for j in range(length):
            if bin_str[j] == "1":
                indexes.append(j)
        yield tuple(indexes)

# 文字列を指定位置に挿入
# (注意)indexesはソートされている必要があります。
def insert_str(target_str, indexes, str_inserted):
    strs = []
    start_index = 0
    if indexes == ():
        return target_str
    for value in indexes:
        strs.append(target_str[start_index:value + 1])
        start_index = value + 1
    strs.append(target_str[start_index:])
    return str_inserted.join(strs)

