def sum_digit(s, d=10, mod=-1):
    n = len(s)
    ret = 0

    def _pow(a, b):
        if mod == -1:
            return pow(a, b)
        return pow(a, b, mod)

    def _contribute(k):
        r = _pow(2, n-1-k) * ((d-1)* _pow(d, k) - _pow(2, k))
        if mod == -1:
            r //= d-2
        else:
            div = pow(d-2, mod - 2, mod)
            r *= div
        return r


    for i, si in enumerate(s[::-1]):
        ret += _contribute(i) * int(si)
    return ret


