def calc_max_sum(N):
    sum_ = 0
    combination_num = 2 ** (len(str(N)) - 1)
    for i in range(combination_num):
        num = i
        tmp = str(N)[0]
        for j in range(1, len(str(N))):
            if num % 2 == 1:
                tmp += "+"
            tmp += str(N)[j]
            num //= 2
        sum_ += sum(map(int, tmp.split("+")))
    return sum_


